	private boolean moveSelectedQuests(double x, double y) {
		for (Movable movable : selectedObjects) {
			if (movable.getChapter() == selectedChapter) {
				movable.requestMove(selectedChapter, movable.getX() + x, movable.getY() + y);
			}
		}

		return true;
	}

	private boolean copyObjectsToClipboard() {
		Movable toCopy = null;

		if (selectedObjects.size() > 1) {
			displayError(Component.translatable("ftbquests.quest.cannot_copy_many"));
		} else if (selectedObjects.isEmpty()) {
			// no objects selected: copy hovered object if there is one
			toCopy = questPanel.getWidgets().stream()
					.filter(w -> w instanceof QuestPositionableButton && w.isMouseOver())
					.map(w -> ((QuestPositionableButton) w).moveAndDeleteFocus())
					.findFirst()
					.orElse(null);
		} else {
			// one object selected
			toCopy = selectedObjects.getFirst();
		}

		if (toCopy != null) {
			toCopy.copyToClipboard();
			Minecraft.getInstance().getToasts().addToast(new CustomToast(Component.translatable("ftbquests.quest.copied"),
					Icons.INFO, Component.literal(toCopy.getTitle().getString())));
			return true;
		}

		return false;
	}

	private boolean pasteSelectedQuest(boolean withDeps, Chapter chapter) {
		return QuestObjectBase.parseHexId(getClipboardString()).map(id -> {
			Pair<Double, Double> qxy = getSnappedXY();
			return switch (file.getBase(id)) {
				case Quest quest -> {
					NetworkManager.sendToServer(new CopyQuestMessage(quest.getId(), chapter.getId(), qxy.getFirst(), qxy.getSecond(), withDeps));
					yield true;
				}
				case ChapterImage img -> {
					NetworkManager.sendToServer(new CopyChapterImageMessage(img.getId(), chapter.getId(), qxy.getFirst(), qxy.getSecond()));
					yield true;
				}
				case null, default -> false;
			};
		}).orElse(false);
	}

	private boolean pasteSelectedQuestLinks(Chapter chapter) {
		String clip = getClipboardString();
		if (clip.isEmpty()) return false;

		return QuestObjectBase.parseHexId(clip).map(id -> {
			if (file.getQuest(id) == null) return false;
			Pair<Double,Double> qxy = getSnappedXY();
			QuestLink link = new QuestLink(0L, chapter, id);
			link.setPosition(qxy.getFirst(), qxy.getSecond());
			NetworkManager.sendToServer(CreateObjectMessage.requestCreation(link, false));
			return true;
		}).orElse(false);
	}

	private Pair<Double,Double> getSnappedXY() {
		double snap = 1D / file.getGridScale();
		double qx = Mth.floor(questPanel.questX * snap + 0.5D) / snap;
		double qy = Mth.floor(questPanel.questY * snap + 0.5D) / snap;
		return Pair.of(qx,qy);
	}

	private boolean handleDeletion(boolean force) {
		if (!selectedObjects.isEmpty()) {
			if (force) {
				deleteSelectedObjects();
			} else {
				Component title = Component.translatable("delete_item", Component.translatable("ftbquests.objects", selectedObjects.size()));
				getGui().openYesNo(title, Component.empty(), this::deleteSelectedObjects);
			}
		} else {
			getHoveredObject().ifPresent(m -> {
				if (force) {
					file.deleteObjects(List.of(m.getMovableID()));
				} else {
					Component title = Component.translatable("delete_item", Component.literal("'").append(m.getTitle()).append("'"));
					getGui().openYesNo(title, Component.empty(), () -> file.deleteObjects(List.of(m.getMovableID())));
				}
			});
		}
		return true;
	}

	private Optional<Movable> getHoveredObject() {
		return questPanel.getWidgets().stream()
				.filter(w -> w instanceof QuestPositionableButton && w.isMouseOver())
				.map(w -> ((QuestPositionableButton) w).moveAndDeleteFocus())
				.findFirst();
	}

	void deleteSelectedObjects() {
		List<Long> toDelete = selectedObjects.stream().map(Movable::getMovableID).toList();
		file.deleteObjects(toDelete);
		selectedObjects.clear();
	}

	double moveStep() {
		return Screen.hasShiftDown() ? 0.1 : 0.5;
	}

	@Override
	public boolean keyPressed(Key key) {
		if (super.keyPressed(key)) {
			return true;
		}

		if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RELOAD_THEME)) {
			reloadTheme(!isShiftKeyDown());
			return true;
		}

		if (file.canEdit()) {
			if (questPanel.bezierController.isActive()) {
				if (key.enter()) {
					questPanel.finishEditingBezierControlPoints(true);
					return true;
				} else if (key.esc()) {
					questPanel.finishEditingBezierControlPoints(false);
					return true;
				}
			}

			if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RELOAD_THEME)) {
				reloadTheme(!isShiftKeyDown());
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_DELETE)) {
				return handleDeletion(false);
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_FORCE_DELETE)) {
				return handleDeletion(true);
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_SELECT_ALL)) {
				if (selectedChapter != null) {
					selectedObjects.addAll(selectedChapter.getQuests());
					selectedObjects.addAll(selectedChapter.getQuestLinks());
					selectedObjects.addAll(selectedChapter.getImages());
				}
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_SELECT_NONE)) {
				selectedObjects.clear();
				return true;
			} else if (movingObjects) {
				if (key.matches(FTBQuestsKeyMappings.KEY_GUI_DOWN)) {
					return moveSelectedQuests(0D, moveStep());
				} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_UP)) {
					return moveSelectedQuests(0D, -moveStep());
				} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_LEFT)) {
					return moveSelectedQuests(-moveStep(), 0D);
				} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RIGHT)) {
					return moveSelectedQuests(moveStep(), 0D);
				}
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_COPY)) {
				return copyObjectsToClipboard();
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_PASTE)) {
				if (selectedChapter != null) {
					if (key.modifiers.alt()) {
						return pasteSelectedQuestLinks(selectedChapter);
					} else {
						return pasteSelectedQuest(!key.modifiers.shift(), selectedChapter);
					}
				}
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_REWARD_TABLES)) {
				new RewardTablesScreen(this).openGui();
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_UNDO)) {
				NetworkManager.sendToServer(UndoRedoRequestMessage.undo());
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_REDO)) {
				NetworkManager.sendToServer(UndoRedoRequestMessage.redo());
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_COMPLETE_OBJ)) {
				getHoveredObject().ifPresent(m -> handleProgressChange(m, false));
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RESET_OBJ)) {
				getHoveredObject().ifPresent(m -> handleProgressChange(m, true));
				return true;
			} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_SAVE)) {
				if (BaseScreen.isShiftKeyDown()) {
					FTBQuestsClient.saveLocally();
				} else {
					NetworkManager.sendToServer(ForceSaveMessage.INSTANCE);
				}
				return true;
			}
		}

		if (key.esc() && !selectedObjects.isEmpty() && !anyModalPanelOpen() && !questPanel.bezierController.isActive()) {
			selectedObjects.clear();
			return true;
		} else if (super.keyPressed(key)) {
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_QUESTS)) {
			closeGui(true);
			return true;
		}

		if (getViewedQuest() != null) {
			return false;
		}

		if (key.matches(FTBQuestsKeyMappings.KEY_GUI_NEXT_CHAPTER)) {
			return cycleChapter(1);
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_PREV_CHAPTER)) {
			return cycleChapter(-1);
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RECENTER)) {
			questPanel.resetScroll();
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_TOGGLE_CROSSHAIRS)) {
			grid = !grid;
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_ZOOM_RESET)) {
			addZoom((16 - zoom) / 4.0);
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_PLAYER_PREFS)) {
			FTBQuestsClientConfig.openSettings(doesGuiPauseGame());
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_EXT_INFO)) {
			showExtendedInfo = true;
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_DOWN)) {
			questPanel.setScrollY(questPanel.getScrollY() + questPanel.getScrollStep() * moveStep());
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_UP)) {
			questPanel.setScrollY(questPanel.getScrollY() - questPanel.getScrollStep() * moveStep());
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_LEFT)) {
			questPanel.setScrollX(questPanel.getScrollX() - questPanel.getScrollStep() * moveStep());
			return true;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_RIGHT)) {
			questPanel.setScrollX(questPanel.getScrollX() + questPanel.getScrollStep() * moveStep());
			return true;
		}

		return false;
	}

	private void handleProgressChange(Movable movable, boolean resetting) {
		QuestObject qob = file.get(movable.getMovableID());
		if (qob != null) {
			handleProgressChange(qob, resetting);
		}
	}

	private void handleProgressChange(QuestObjectBase qob, boolean resetting) {
		getGui().openYesNo(Component.translatable(resetting ? "ftbquests.gui.reset_progress_q" : "ftbquests.gui.complete_instantly_q"),
				qob.getTitle(),
				() -> ChangeProgressMessage.sendToServer(FTBQuestsClient.getClientPlayerData(), qob,
						progressChange -> progressChange.setReset(resetting)));
	}

	@Override
	public void keyReleased(Key key) {
		super.keyReleased(key);
		if (key.matches(FTBQuestsKeyMappings.KEY_GUI_EXT_INFO)) {
			showExtendedInfo = false;
		} else if (key.matches(FTBQuestsKeyMappings.KEY_GUI_SEARCH)) {
			openQuestSelectionGUI();
		}
	}

	private boolean cycleChapter(int offset) {
		List<Chapter> visibleChapters = file.getVisibleChapters(file.selfTeamData);
		int index = visibleChapters.indexOf(selectedChapter) + offset;
		if (selectedChapter != null && visibleChapters.size() > 1) {
			selectChapter(visibleChapters.get(MathUtils.mod(index, visibleChapters.size())));
		}
		return true;
	}

	private void openQuestSelectionGUI() {
		ConfigQuestObject<QuestObject> c = new ConfigQuestObject<>(QuestObjectType.CHAPTER.or(QuestObjectType.QUEST).or(QuestObjectType.QUEST_LINK));
		new SelectQuestObjectScreen<>(c, accepted -> {
			if (accepted) {
				if (c.getValue() instanceof Chapter chapter) {
					selectChapter(chapter);
				} else if (c.getValue() instanceof Quest quest) {
					zoom = 20;
					selectChapter(quest.getChapter());
					questPanel.scrollTo(quest.getX(), quest.getY());
					open(quest, true);
				} else if (c.getValue() instanceof QuestLink link) {
					zoom = 20;
					selectChapter(link.getChapter());
					questPanel.scrollTo(link.getX(), link.getY());
					open(link, true);
				}
			}
			QuestScreen.this.openGui();
		}).openGui();
	}

	@Override
	public void tick() {
		if (!refreshPending.isEmpty()) {
			refreshPending.forEach(Panel::refreshWidgets);
			refreshPending.clear();
		}

		if (pendingPersistedData != null) {
			restorePersistedScreenData(file, pendingPersistedData);
			pendingPersistedData = null;
		}

		if (selectedChapter != null && !selectedChapter.isValid()) {
			selectChapter(null);
		}

		if (selectedChapter == null) {
			selectChapter(file.getFirstVisibleChapter(file.selfTeamData));
		}

		super.tick();
	}

	public int getZoom() {
		return zoom;
	}

	public double getQuestButtonSize() {
		return getZoom() * 3D / 2D;
	}

	public double getQuestButtonSpacing() {
		return getZoom() * ThemeProperties.QUEST_SPACING.get(selectedChapter) / 4D;
	}

	public void addZoom(double up) {
		int z = zoom;
		zoom = (int) Mth.clamp(zoom + up * 4, 4, 28);

		if (zoom != z) {
			grabbed = null;
			questPanel.withPreservedPos(QuestPanel::resetScroll);
		}
	}

	@Override
	public void drawBackground(GuiGraphics graphics, Theme theme, int x, int y, int w, int h) {
		QuestTheme.setFallbackQuestObject(selectedChapter);
		super.drawBackground(graphics, theme, x, y, w, h);

		int pw = 20;

		Color4I borderColor = ThemeProperties.WIDGET_BORDER.get(selectedChapter);
		Color4I backgroundColor = ThemeProperties.WIDGET_BACKGROUND.get(selectedChapter);

		if (!chapterPanel.expanded) {
			borderColor.draw(graphics, x + pw - 1, y + 1, 1, h - 2);
			backgroundColor.draw(graphics, x + 1, y + 1, pw - 2, h - 2);
		}

		borderColor.draw(graphics, x + w - pw, y + 1, 1, h - 2);
		backgroundColor.draw(graphics, x + w - pw + 1, y + 1, pw - 2, h - 2);

		if (grabbed != null) {
			int mx = getMouseX();
			int my = getMouseY();
			if (questPanel.isDraggingSelectionBox()) {
				int boxX = Math.min(prevMouseX, mx);
				int boxY = Math.min(prevMouseY, my);
				int boxW = Math.abs(mx - prevMouseX);
				int boxH = Math.abs(my - prevMouseY);
				GuiHelper.drawHollowRect(graphics, boxX, boxY, boxW, boxH, Color4I.DARK_GRAY, false);
				Color4I.DARK_GRAY.withAlpha(40).draw(graphics, boxX, boxY, boxW, boxH);
			} else if (grabbed.isLeft()) {
				if (scrollWidth > questPanel.width) {
					questPanel.setScrollX(Math.clamp(questPanel.getScrollX() + (prevMouseX - mx), 0, scrollWidth - questPanel.width));
				} else {
					questPanel.setScrollX((scrollWidth - questPanel.width) / 2);
				}

				if (scrollHeight > questPanel.height) {
					questPanel.setScrollY(Math.clamp(questPanel.getScrollY() + (prevMouseY - my), 0, scrollHeight - questPanel.height));
				} else {
					questPanel.setScrollY((scrollHeight - questPanel.height) / 2);
				}

				prevMouseX = mx;
				prevMouseY = my;
			}
		}
	}

	void selectAllQuestsInBox(int mouseX, int mouseY, double scrollX, double scrollY) {
		int x1 = Math.min(prevMouseX, mouseX);
		int x2 = Math.max(prevMouseX, mouseX);
		int y1 = Math.min(prevMouseY, mouseY);
		int y2 = Math.max(prevMouseY, mouseY);
		Rect2i rect = new Rect2i(x1, y1, x2 - x1, y2 - y1);

		if (!Screen.hasControlDown()) selectedObjects.clear();

		questPanel.getWidgets().forEach(w -> {
			if (w instanceof QuestPositionableButton qb && rect.contains((int) (w.getX() - scrollX), (int) (w.getY() - scrollY))) {
				toggleSelected(qb.moveAndDeleteFocus());
			}
		});
	}

