		hideExcludedQuests = false;
		verifyOnLoad = false;

		allPresets = VisualPresets.EMPTY;
		presetName = "";

		allTasks = null;
		allQuests = null;

		translationManager = new TranslationManager();
		fallbackLocale = TranslationManager.DEFAULT_FALLBACK_LOCALE;
	}

